"""Concise retained HF pharmacology and trial explanations."""
from cardiology_15_compact_antiplatelets import B,S
edits={
'04-010':S('ACE Inhibitor–ARNI Transition',[B('**Allow ≥36 hours after the last ACE inhibitor dose before ARNI.**','Overlapping neprilysin and ACE inhibition increases bradykinin-associated angioedema risk.')],
 'Prescribing Checks',[B('**Do not overlap ARNI with an ACE inhibitor or additional ARB.**','Sacubitril/valsartan already contains an ARB.'),B('**Check angioedema history, BP, potassium and renal function.**','The ACE washout is distinct from switching an ARB; titrate only as tolerated.')]),
'04-011':S('ARNI Starting Dose',[B('**No or low prior ACE inhibitor/ARB exposure: start 24/26 mg twice daily.**','The reduced start reflects limited prior RAS blockade, not an automatic prohibition from moderate CKD.')],
 'Titration',[B('**Increase every 2–4 weeks as tolerated toward 97/103 mg twice daily.**','Monitor hypotension, creatinine and potassium.'),B('**Correct volume depletion and review interacting drugs.**','Do not omit an indicated ACE-inhibitor washout when one has actually been taken.')]),
'04-012':S('Evidence-Based HFrEF Beta Blockers',[B('**Metoprolol succinate ER, carvedilol and bisoprolol** have outcome evidence.','Metoprolol succinate 12.5 mg daily is an appropriate low start in this compensated patient.')],
 'Initiation and Monitoring',[B('**Start after hemodynamic stabilization and titrate gradually.**','Check HR, BP, congestion and conduction; do not initiate during active hypoperfusion.'),B('**Formulation matters.**','Metoprolol tartrate is not the trial-supported succinate extended-release regimen for HFrEF outcome treatment.')]),
'04-013':S('MRA Eligibility',[B('**Initiate when eGFR >30 mL/min/1.73 m² and potassium <5.0 mmol/L** under AHA/ACC/HFSA 2022.','Potassium 5.2 fails the entry threshold despite adequate eGFR.')],
 'Correct and Reassess',[B('**Review supplements, salt substitutes, NSAIDs and renal changes.**','Repeat potassium after addressing reversible causes.'),B('**Monitor closely after initiation or dose changes.**','If potassium cannot be maintained below 5.5 during treatment, discontinue the MRA to avoid life-threatening hyperkalemia.')]),
'04-014':S('Dapagliflozin for HF',[B('**Use 10 mg daily for the HF indication**, independent of diabetes.','The patient’s eGFR 38 permits initiation under the cited US label.')],
 'Safety',[B('**Assess volume status, kidney function and ketoacidosis risk.**','Sick-day and perioperative interruption advice matters even without marked hyperglycemia.'),B('**Glycemic efficacy and HF eligibility differ.**','A reduced glucose-lowering effect at lower eGFR does not remove established HF benefit; watch genital infection and dehydration.')]),
'04-016':S('Creatinine After RAS Blockade',[B('**Rise from 1.5 to 1.8 mg/dL = 20%.**','Stable BP, potassium and volume status support continuation with monitoring.')],
 'When to Investigate',[B('**A rise >30% within four weeks warrants assessment** under KDIGO 2024.','Consider hypovolemia, NSAIDs, renal artery disease or intercurrent illness.'),B('**Do not equate a small hemodynamic rise with progressive kidney injury.**','Reassess significant hypotension, hyperkalemia or continuing deterioration promptly.')]),
'04-017':S('Potassium Binders in HFrEF',[B('**Patiromer can reduce hyperkalemia and facilitate RAS-inhibitor/MRA use.**','DIAMOND primarily informs potassium control and treatment maintenance.')],
 'Evidence Boundary',[B('**This does not establish an independent mortality benefit from the binder.**','Separate enabling disease-modifying treatment from directly proving improved clinical outcomes.'),B('**Monitor potassium, magnesium and medication timing.**','Correct reversible causes and follow product-specific separation from other oral drugs.')]),
'04-018':S('Remission After Dilated Cardiomyopathy',[B('**TRED-HF found frequent relapse after withdrawal.**','Normalized EF and absence of symptoms do not reliably identify cure.')],
 'Continued Care',[B('**Continue indicated HF therapy when tolerated.**','Monitor symptoms, ventricular function and precipitating factors.'),B('**Necessary changes require individualized supervision.**','The evidence argues against routine blanket withdrawal; it does not require ignoring hypotension, toxicity or contraindications.')]),
'04-020':S('NSAID-Related HF Deterioration',[B('**Renal prostaglandin inhibition promotes sodium retention and blunts diuresis.**','BP can rise and renal perfusion can deteriorate, especially with RAS blockade and diuretics.')],
 'Management',[B('**Withdraw the contributing NSAID and reassess congestion, renal function and potassium.**','Choose an appropriate alternative analgesic and adjust HF treatment to clinical status.'),B('**Ask about nonprescription drugs.**','A new medicine can explain deterioration despite good adherence to the existing HF regimen.')]),
'04-021':S('Ivabradine Selection',[B('**Symptomatic stable HFrEF, EF ≤35%, sinus rhythm and resting HR ≥70/min** despite maximally tolerated beta blockade fit the indication.')],
 'Use and Monitoring',[B('**Typical start: 5 mg twice daily with food**, using a lower start in selected vulnerable patients.','Titrate to HR/tolerance, maximum 7.5 mg twice daily.'),B('**Monitor bradycardia, AF and luminous visual phenomena.**','The drug targets sinus If current; it does not control AF ventricular rate or replace foundational HF therapy.')]),
'04-022':S('Hydralazine–Isosorbide Dinitrate',[B('**Add-on benefit is established in self-identified African American patients with persistent NYHA III–IV HFrEF** receiving appropriate therapy.')],
 'Practical Use',[B('**Fixed combination commonly starts at hydralazine 37.5 mg/ISDN 20 mg three times daily.**','Titrate toward 75/40 mg three times daily as tolerated.'),B('**Monitor headache, hypotension and adherence.**','Avoid nitrate combinations with PDE5 inhibitors or riociguat; consider hydralazine-associated lupus symptoms.')]),
'04-023':S('Digoxin Toxicity Risk',[B('**Renal deterioration plus amiodarone can raise digoxin exposure.**','Nausea and new bradycardia require withholding and urgent assessment, not automatic continuation of the previously tolerated dose.')],
 'Assessment',[B('**Check ECG, potassium, magnesium, renal function and a correctly timed level.**','Interpret concentrations after distribution, generally ≥6 hours after dosing, with the clinical picture.'),B('**Life-threatening toxicity warrants digoxin-specific antibody fragments.**','A concentration alone neither proves nor excludes clinically important toxicity.')]),
'04-024':S('DIGIT-HF',[B('**Digitoxin reduced all-cause death or first worsening-HF hospitalization as a composite.**','The study tested carefully monitored digitoxin, not unrestricted cardiac-glycoside prescribing.')],
 'Drug and Endpoint Specificity',[B('**Do not infer an identical effect for digoxin.**','The drugs differ in pharmacokinetics, and separate trials must be interpreted on their own endpoints.'),B('**Neither replaces foundational HFrEF treatment.**','Narrow therapeutic margins require attention to dose, interactions, electrolytes and toxicity.')]),
'04-025':S('Vericiguat After Worsening HF',[B('**VICTORIA studied symptomatic reduced-EF HF with a recent worsening event.**','Soluble guanylate cyclase stimulation is an additional strategy after foundational treatment.')],
 'Selection and Follow-up',[B('**Assess BP, pregnancy risk and interacting vasodilator pathways.**','Use the current label for initiation and titration; monitor hypotension and anemia.'),B('**Match the residual indication.**','Sinus rate 62 does not fit ivabradine’s residual-tachycardia criterion, and the iron indices given do not establish trial-defined iron deficiency.')]),
'04-028':S('SERVE-HF',[B('**The tested ASV strategy increased mortality in HFrEF with predominant central sleep apnea** despite improving breathing events.')],
 'Endpoint and Device Specificity',[B('**Suppressing apnea is not proof of cardiovascular benefit.**','Later trials and device differences require specialist interpretation rather than assuming a uniform class effect.'),B('**Treat underlying HF and characterize the sleep disorder.**','Do not substitute obstructive-apnea evidence or an event-count improvement for safety in this phenotype.')]),
'04-029':S('DELIVER',[B('**Dapagliflozin improved the worsening-HF/CV-death composite in LVEF >40%, including patients without diabetes.**')],
 'Clinical Interpretation',[B('**A composite benefit does not establish a separately significant CV-mortality reduction.**','Hospitalizations and urgent HF visits are important components.'),B('**Confirm the HF syndrome rather than prescribing from EF alone.**','Assess volume status, renal eligibility, genital infection and ketoacidosis precautions before treatment.')]),
'04-030':S('Finerenone HF Dose',[B('**Initial eGFR 25 to <60: start 10 mg daily; target 20 mg daily.**','For initial eGFR ≥60, the HF start/target is 20/40 mg daily under the cited label.')],
 'Laboratory and Interaction Review',[B('**Check potassium and eGFR before treatment and at four weeks.**','Do not initiate with potassium >5.0 or eGFR <25; later changes follow the indication-specific adjustment table.'),B('**Avoid duplicate MRA treatment and prohibited CYP3A interactions.**','Do not copy the diabetic-CKD dose ceiling into the HF regimen.')]),
'04-031':S('Obesity-Related HFpEF Trials',[B('**STEP-HFpEF:** semaglutide improved health status, physical limitations and weight.','**SUMMIT:** tirzepatide also improved a CV-death/worsening-HF composite.')],
 'Avoid Interchangeable Claims',[B('**A symptom/weight endpoint is not a mortality endpoint.**','Neither result establishes a stand-alone survival benefit for every incretin agent.'),B('**Select the obesity-related HFpEF phenotype and monitor tolerability.**','Address volume status, nutrition and adverse effects alongside continuing indicated HF care.')]),
'04-046':S('ADVOR',[B('**Acetazolamide 500 mg IV daily added to standardized loop therapy improved successful decongestion within three days.**')],
 'Clinical Boundaries',[B('**The endpoint was decongestion, not proven mortality benefit.**','The studied background therapy and renal eligibility matter.'),B('**Monitor renal function, bicarbonate and electrolytes.**','Proximal bicarbonate/natriuretic action complements loop diuresis; reassess acidosis and volume depletion rather than using a fixed course blindly.')]),
'04-050':S('STRONG-HF',[B('**Rapid tolerated optimization was coupled with frequent early review.**','The intervention included clinical assessment and laboratory monitoring, not simply larger discharge prescriptions.')],
 'Implementation',[B('**Start before discharge when stable; titrate with early follow-up.**','Assess BP, HR, congestion, creatinine and potassium.'),B('**Maintain safety thresholds and patient-specific tolerance.**','Do not infer that rapid escalation without monitoring reproduces the trial benefit.')]),
'04-058':S('DOREMI',[B('**No significant primary-composite difference was demonstrated between milrinone and dobutamine.**','A nonsignificant superiority test is not proof of equivalence.')],
 'Physiology Guides Choice',[B('**Dobutamine:** beta-adrenergic inotropy, rapid titration and possible tachycardia.','**Milrinone:** PDE3-mediated inodilation, renal accumulation and hypotension risk.'),B('**Reassess perfusion and adverse effects continuously.**','Neither drug fixes the underlying infarct, mechanical lesion or persistent shock cause.')]),
'04-060':S('IABP-SHOCK II',[B('**Routine IABP did not reduce 30-day mortality** in the studied infarct-related shock population undergoing early revascularization.')],
 'What Remains Individualized',[B('**Selected mechanical complications or bridging needs are different questions.**','Do not extrapolate the trial to eliminate every possible support indication.'),B('**Prioritize definitive treatment and shock reassessment.**','Physiological improvement alone does not establish a survival benefit from routine device deployment.')]),
'04-061':S('ECLS-SHOCK',[B('**Routine early ECLS did not lower 30-day mortality** and increased important bleeding and vascular complications.')],
 'Rescue Versus Routine Use',[B('**The result does not prove that no selected patient can benefit.**','Assess reversibility, neurological prognosis, contraindications and alternative support.'),B('**Device complications are part of net benefit.**','A greater ability to sustain circulation does not by itself establish improved patient-centered outcomes.')]),
'04-062':S('DanGer-Shock',[B('**A microaxial flow pump lowered 180-day mortality in selected STEMI-related shock**, with more treatment-related complications.')],
 'Population Matching',[B('**Review LV-predominant physiology, timing, neurological status and device suitability.**','Do not automatically extend the result to every arrest survivor, isolated RV shock or mechanical complication.'),B('**Balance survival evidence against bleeding, limb injury and renal complications.**','Use an experienced multidisciplinary shock pathway alongside revascularization.')])
}
